def is_palindrome(number):
    return str(number) == str(number)[::-1]

def even_odd_palindrome(n):
    """Return a tuple containing counts of odd and even integer palindromes within the range [1, n]."""
    count_even = 0
    count_odd = 0

    for i in range(1, n + 1):
        if is_palindrome(i):
            if i % 2 == 0:
                count_even += 1
            else:
                count_odd += 1

    return (count_even, count_odd)
```

